    // tenure check here exactly as the i64 `saturating_sub` does on chain.
    const elapsed = nowSeconds - gateway.startTimestamp;
    if (elapsed < GATEWAY_DISCOUNT_MIN_TENURE_SECONDS)
        return 'tenure';
